import pandas as pd


def _null_safe_diff_numeric(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _null_safe_diff_label(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    a_str = str(a).rstrip(" ")
    b_str = str(b).rstrip(" ")
    return a_str != b_str


def run(inputs: dict) -> dict:
    snap_prev = inputs["snap_prev"].copy()
    snap_curr = inputs["snap_curr"].copy()

    merged = pd.merge(
        snap_prev,
        snap_curr,
        on=["region", "sku"],
        how="outer",
        suffixes=("_prev", "_curr"),
        indicator=True,
    )

    out_rows = []

    for _, row in merged.iterrows():
        region = row["region"]
        sku = row["sku"]
        merge_flag = row["_merge"]

        if merge_flag == "left_only":
            out_rows.append(
                {
                    "region": region,
                    "sku": sku,
                    "change_type": "D",
                    "changed_cols": None,
                }
            )
        elif merge_flag == "right_only":
            out_rows.append(
                {
                    "region": region,
                    "sku": sku,
                    "change_type": "I",
                    "changed_cols": None,
                }
            )
        else:
            price_diff = _null_safe_diff_numeric(row["price_prev"], row["price_curr"])
            stock_diff = _null_safe_diff_numeric(row["stock_prev"], row["stock_curr"])
            label_diff = _null_safe_diff_label(row["label_prev"], row["label_curr"])

            if price_diff or stock_diff or label_diff:
                changed = []
                if price_diff:
                    changed.append("price")
                if stock_diff:
                    changed.append("stock")
                if label_diff:
                    changed.append("label")
                out_rows.append(
                    {
                        "region": region,
                        "sku": sku,
                        "change_type": "U",
                        "changed_cols": ",".join(changed),
                    }
                )
            # else: no change, no row

    change_log = pd.DataFrame(
        out_rows, columns=["region", "sku", "change_type", "changed_cols"]
    )

    return {"change_log": change_log}
